import { strictInteger } from '../';

describe('strictInteger mask', () => {
  it('should not mask null', () => {
    expect(strictInteger(null)).toEqual(null);
  });

  it('should not mask numbers', () => {
    expect(strictInteger('531')).toEqual('531');
  });

  it('should parse out the first available piece', () => {
    expect(strictInteger('500aa3.2aa7')).toEqual('500');
    expect(strictInteger('aa31.2aa7aa5')).toEqual('31');
  });

  it('should mask letters', () => {
    expect(strictInteger('aa9bb')).toEqual('9');
  });

  it('should allow negative', () => {
    expect(strictInteger('-53')).toEqual('-53');
  });

  it('should not allow decimals', () => {
    expect(strictInteger('-53.2')).toEqual('-53');
  });

  it('should not allow negative signs in the middle', () => {
    expect(strictInteger('-5-3.27')).toEqual('-5');
  });
});
